// ─── File: ZeroTrustDemo.java ───
// Enforces zero-trust: mTLS → JWT → dynamic policy → anomaly detection.
package com.bank.gateway.demo;

import java.math.BigDecimal;
import java.util.logging.*;

public class ZeroTrustDemo {
    private static final Logger log = Logger.getLogger("ZeroTrust");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new ZtLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ZeroTrustGateway gateway = new ZeroTrustGateway();

        log.info("=== Normal authorized transfer (passes all 4) ===");
        gateway.handle(new Request("known-client", "valid:rajesh:transfer", "transfer",
                new BigDecimal("50000"), "Mumbai"));

        log.info("=== Unknown client (fails mTLS) ===");
        gateway.handle(new Request("unknown-client", "valid:rajesh:transfer", "transfer",
                new BigDecimal("50000"), "Mumbai"));

        log.info("=== Valid token but missing scope (fails policy) ===");
        gateway.handle(new Request("known-client", "valid:priya:read", "transfer",
                new BigDecimal("50000"), "Mumbai"));

        log.info("=== Risky high-amount + unusual location (fails policy) ===");
        gateway.handle(new Request("known-client", "valid:rajesh:transfer", "transfer",
                new BigDecimal("900000"), "Unknown-Country"));

        log.info("=== Burst from one user (trips anomaly detection) ===");
        for (int i = 0; i < 7; i++) {
            gateway.handle(new Request("known-client", "valid:rajesh:transfer", "transfer",
                    new BigDecimal("1000"), "Mumbai"));
        }
    }
}

// ─── Would be in core/Request.java ───
class Request {
    final String clientCertId; final String jwt; final String action;
    final BigDecimal amount; final String location;
    Request(String clientCertId, String jwt, String action, BigDecimal amount, String location) {
            this.clientCertId = clientCertId;
            this.jwt = jwt
            this.action = action;
        this.amount = amount; this.location = location;
    }
}

// ─── Would be in security/MtlsVerifier.java ───
class MtlsVerifier {
    private final java.util.Set<String> known = java.util.Set.of("known-client", "mobile-app", "web-app");
    boolean verify(String clientCertId) { return known.contains(clientCertId); } // client cert must be trusted
}

// ─── Would be in security/JwtValidator.java ───
class JwtValidator {
    // token format for the demo: "valid:<user>:<scope>"
    static class Claims { final String user; final String scope;
            Claims(String user, String scope) { this.user = user;
            this.scope = scope; } }
    Claims validate(String jwt) {
        if (jwt == null || !jwt.startsWith("valid:")) return null; // signature/expiry failed
        String[] p = jwt.split(":");
        return new Claims(p[1], p[2]);
    }
}

// ─── Would be in security/PolicyEngine.java ───
class PolicyEngine {
    // Dynamic, context-aware authorization (like Open Policy Agent rules).
    boolean allow(String action, JwtValidator.Claims claims, BigDecimal amount, String location) {
        if (!claims.scope.equals(action)) return false;                       // least privilege: scope must match
        boolean riskyLocation = !java.util.Set.of("Mumbai", "Delhi", "Pune").contains(location);
        if (action.equals("transfer") && amount.compareTo(new BigDecimal("500000")) > 0 && riskyLocation)
            return false;                                                     // high amount + unusual place → deny
        return true;
    }
}

// ─── Would be in security/AnomalyDetector.java ───
class AnomalyDetector {
    private final java.util.Map<String, Integer> counts = new java.util.HashMap<>();
    private final int perWindowLimit;
    AnomalyDetector(int perWindowLimit) { this.perWindowLimit = perWindowLimit; }
    boolean isAnomalous(String user) {
        int c = counts.merge(user, 1, Integer::sum);
        return c > perWindowLimit; // sudden burst beyond normal behavior
    }
}

// ─── Would be in core/ZeroTrustGateway.java ───
class ZeroTrustGateway {
    private static final Logger log = Logger.getLogger("ZeroTrust");
    private final MtlsVerifier mtls = new MtlsVerifier();
    private final JwtValidator jwt = new JwtValidator();
    private final PolicyEngine policy = new PolicyEngine();
    private final AnomalyDetector anomaly = new AnomalyDetector(5);

    String handle(Request req) {
        // 1) mTLS: is the client a trusted, known entity?
        if (!mtls.verify(req.clientCertId)) {
            log.severe(() -> "DENY mTLS: unknown client " + req.clientCertId);
            return "403-mtls";
        }
        // 2) JWT: is the request-level identity proven?
        JwtValidator.Claims claims = jwt.validate(req.jwt);
            if (claims == null) { log.severe("DENY JWT: invalid token");
            return "401-jwt"; }
        // 3) Dynamic policy: is this exact action allowed under current context?
        if (!policy.allow(req.action, claims, req.amount, req.location)) {
            log.warning(() -> "DENY policy: user=" + claims.user + " action=" + req.action
                    + " amount=" + req.amount + " loc=" + req.location);
            return "403-policy";
        }
        // 4) Anomaly detection: continuous verification of behavior.
        if (anomaly.isAnomalous(claims.user)) {
            log.severe(() -> "DENY anomaly: burst detected for " + claims.user);
            return "429-anomaly";
        }
        log.info(() -> "ALLOW " + claims.user + " action=" + req.action + " amount=" + req.amount);
        return "200-ok";
    }
}

